import{z as B,x as p,o as l,c as d,q as r,j as n,D as E,d as t,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"层次 MoE","description":"","frontmatter":{"title":"层次 MoE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hierarchical-moe.md","filePath":"llm/hierarchical-moe.md","lastUpdated":1791063341000}'),A={name:"llm/hierarchical-moe.md"};function m(h,a,c,u,C,D){const o=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="层次-moe" tabindex="-1">层次 MoE <a class="header-anchor" href="#层次-moe" aria-label="Permalink to &quot;层次 MoE&quot;">​</a></h1><div class="epigraph"><p>先选一组或一台设备上的专家簇，再在簇内选个体；路由拆成树，通信与特化都沿树发生。</p><footer>—— 层次混合专家的经典形式见 Eigen et al., 2013；当代稀疏 LLM 中的共享加路由专家见 Dai et al., DeepSeekMoE, 2024</footer></div><p><a href="/llm/peer-million-experts">上一课</a>在平坦表上近邻检索。<a href="/llm/node-limited-routing">节点受限路由</a> 已经是一棵浅树：先设备后专家。本课把树写正式：多层门，每层只在上一层选中的子集里打分。DeepSeekMoE 的共享专家 + 细粒度路由专家是一种两层（共享为常开组）。后课通信比把树的扇出定量化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平坦 top-\\(k\\) 在 \\(N\\) 大时门贵、通信贵、特化轴单一。PEER 用向量检索回避 \\(\\Theta(N)\\) 门，但近似索引难训。缺口是<strong>显式层次</strong>：第一层用便宜的门选 \\(G\\) 组，\\(G\\) 小；第二层在组内 \\(N/G\\) 个专家里再选。组可以对应设备、领域、或共享/非共享。</p>',5)),(l(),n(s,null,{default:E(()=>[i(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%BB%99%20token%20%E5%9C%A8%20N%20%E4%B8%AA%E4%B8%93%E5%AE%B6%E9%87%8C%E8%B7%AF%E7%94%B1%22%5D%20--%3E%20F%5B%22%E5%B9%B3%E5%9D%A6%20top-k%EF%BC%9A%E5%85%A8%E8%A1%A8%E6%89%93%E5%88%86%EF%BC%8C%E9%97%A8%E5%BC%80%E9%94%80%20%CE%98(N)%22%5D%0A%20%20T%20--%3E%20HS%5B%22%E5%93%88%E5%B8%8C%EF%BC%9A%E5%9B%BA%E5%AE%9A%E6%A0%91%EF%BC%8C%E9%9B%B6%E8%AE%AD%E7%BB%83%22%5D%0A%20%20T%20--%3E%20PR%5B%22PEER%EF%BC%9A%E5%90%91%E9%87%8F%E6%A3%80%E7%B4%A2%E8%BF%91%E4%BC%BC%E8%BF%91%E9%82%BB%22%5D%0A%20%20T%20--%3E%20LR%5B%22%E5%B1%82%E6%AC%A1%20MoE%EF%BC%9A%E5%85%88%E9%80%89%20G%20%E7%BB%84%EF%BC%8C%E5%86%8D%E7%BB%84%E5%86%85%E9%80%89%20k%22%5D%0A%20%20LR%20--%3E%20BAL%5B%22%E4%B8%A4%E5%B1%82%E9%97%A8%E5%90%84%E8%87%AA%E5%9D%87%E8%A1%A1%EF%BC%8C%E5%90%A6%E5%88%99%E5%A1%8C%E6%88%90%E5%8D%95%E7%BB%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>Eigen 等人较早写出层次 MoE。当代 LLM 不一定引用该名，但共享专家（每个 token 必算）加路由专家（稀疏选）就是两层：一层恒等选共享组，一层稀疏选。课序把它们收成同一设计。</p><p><span class="marginnote">层次不是把 FFN 叠深。树的每一层都是路由，计算仍在叶子专家。中间节点通常没有 MLP，只有门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两层例：token 先对 \\(G\\) 个组打分，取 top-1 或 top-2 组，再在组内 top-\\(k\\)。门参数是 \\(d\\times G\\) 加每组 \\(d\\times(N/G)\\)，和为 \\(dN/G\\cdot G + dG=dN+dG\\)，与平坦同阶，但实现上第一次 All-to-All 只在组代表之间。共享专家：\\(G_{\\mathrm{shared}}\\) 对所有 token 常开，相当于树根上的必经叶子，保证公共计算（如高频功能），稀疏枝负责长尾。</p><p><span class="marginnote">All-to-All 是 MoE 里最常见的集合通信：每张卡把自己手上的 token 寄给「被选中专家所在的那张卡」，算完再寄回来。可以想象成整栋楼的人各自把信投到不同楼层——专家在几楼，信就得寄几楼。层次化相当于先按楼栋分拣，跨楼寄送的包裹数就降下来了。</span></p><p>训练要对每层门分别均衡，否则第一层崩成永远选一组，层次名存实亡。无辅助损失偏置应对组级与专家级各设一套水位。</p><h3 id="与-peer、哈希" tabindex="-1">与 PEER、哈希 <a class="header-anchor" href="#与-peer、哈希" aria-label="Permalink to &quot;与 PEER、哈希&quot;">​</a></h3><p>哈希是固定树。PEER 是度量树或 IVF。层次 MoE 是学习的浅树。三者都能把 \\(N\\) 做大；可学习浅树在几十到数千专家上最可控，百万级再考虑检索。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>第一层决定粗特化（代码/自然语言、设备域），第二层决定细特化。序列级均衡若只加在叶子，第一层仍可把整段序列送进同一组——组级也要看直方图。共享专家降低对稀疏枝的依赖，使 \\(k\\) 可以更小而不崩质量，这是细粒度 MoE 能把单专家削窄的前提。</p><p><span class="marginnote">数字实例：取 d=4096、N=256、G=8。组级门是 4096×8 ≈ 3.3 万参数；组内门每组 4096×32 ≈ 13 万参数，八组合计约 105 万——与平坦全表门 4096×256 同量级。层次省的从来不是参数量，而是打分的形状与第一次通信的扇出。</span></p><p>通信：组对齐设备时，第一层几乎是节点受限；不对齐时层次不自动省网。设计树时拓扑优先于语义故事。</p><p><span class="marginnote">共享专家吃掉固定 FLOPs 配额。报稀疏度应写「共享加路由」的激活参数，而不是只写路由 \\(k/N\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>层数多于两级，门的优化与实现复杂度上升很快，LLM 主干少见三层以上。第一层若 \\(G\\) 太大，退回平坦。下一课把这些选择收进通信-计算比，不再引入新的路由哲学。剪枝应先剪叶子再考虑删组，删组等于砍掉一棵子树。</p><p><span class="marginnote">初学者容易以为删专家跟删普通参数一样无关痛痒。删一个叶子专家，只是把它那份流量让给别的专家；删掉一个组等于砍掉整棵子树——该组覆盖的那类输入（比如代码）会整块失去对应的细粒度特化，质量塌方往往集中在特定领域而不是平均掉。</span></p>',16)),(l(),n(s,null,{default:E(()=>[i(o,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%22%5D%20--%3E%20G%5B%22%E7%BB%84%E7%BA%A7%E9%97%A8%22%5D%0A%20%20G%20--%3E%20S%5B%22%E5%85%B1%E4%BA%AB%E4%B8%93%E5%AE%B6%E5%B8%B8%E5%BC%80%22%5D%0A%20%20G%20--%3E%20R%5B%22%E9%80%89%E4%B8%AD%E7%BB%84%E5%86%85%E8%B7%AF%E7%94%B1%E4%B8%93%E5%AE%B6%22%5D%0A%20%20S%20--%3E%20Y%5B%22%E6%B1%82%E5%92%8C%22%5D%0A%20%20R%20--%3E%20Y%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"层次 MoE 用浅树把路由拆成组选择与组内选择；共享专家是常开叶子。"),e("li",null,"每层都要均衡，否则塌成单组。"),e("li",null,"组对齐设备时才自动省通信；语义分组不保证网络收益。"),e("li",null,"报激活参数须包含共享枝。"),e("li",null,"出处：Eigen et al., 2013；Dai et al., 2024。")],-1))])}const f=B(A,[["render",m]]);export{k as __pageData,f as default};
